import{_ as o}from"./chunks/47.C_J93QOY.js";import{_ as r}from"./chunks/1._Wu06lVH.js";import{_ as s}from"./chunks/0.xVPDiwtD.js";import{_ as l}from"./chunks/26.DjOLQpcl.js";import{_ as d}from"./chunks/0.B7TrDeTt.js";import{_ as c}from"./chunks/1.BU1qyW7B.js";import{_ as i}from"./chunks/0.DyB7G7H5.js";import{_ as h}from"./chunks/3.PcdR27wg.js";import{_ as p}from"./chunks/5.BkY6Rw8O.js";import{_ as t}from"./chunks/0.C_OEUMPL.js";import{_ as g}from"./chunks/9._7FszrLL.js";import{_ as m}from"./chunks/11.DPtnPYcq.js";import{_ as u}from"./chunks/100.DMbJtyMU.js";import{_ as f}from"./chunks/community.BdKwbEUF.js";import{_ as w,C as _,o as y,c as b,ak as a,E as x}from"./chunks/framework.sbZkgmEx.js";const v="/projects/AiBlock/en/advanced-kit/assets/1.alBL1bF9.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.1.BUfktSBc.webp",P="/projects/AiBlock/en/advanced-kit/assets/2.1.BAk-fKUi.webp",q="/projects/AiBlock/en/advanced-kit/assets/2.2.B-zWBZGO.webp",S="/projects/AiBlock/en/advanced-kit/assets/3.l20597Ew.webp",B="/projects/AiBlock/en/advanced-kit/assets/4.GEuBm-md.webp",K=JSON.parse('{"title":"3.47 Spinning Swing Ride","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.47 Spinning Swing Ride.md","filePath":"docs/3.Creative Builds/3.47 Spinning Swing Ride.md"}'),z={name:"docs/3.Creative Builds/3.47 Spinning Swing Ride.md"};function T(A,e,j,C,R,E){const n=_("Pdf");return y(),b("div",null,[e[0]||(e[0]=a('<h1 id="_3-47-spinning-swing-ride" tabindex="-1">3.47 Spinning Swing Ride <a class="header-anchor" href="#_3-47-spinning-swing-ride" aria-label="Permalink to &quot;3.47 Spinning Swing Ride&quot;">​</a></h1><h2 id="_3-47-1-lesson-introduction" tabindex="-1">3.47.1 Lesson Introduction <a class="header-anchor" href="#_3-47-1-lesson-introduction" aria-label="Permalink to &quot;3.47.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on a spinning swing ride model, this lesson explores coordinated programming among a motor, a touch sensor, and audiovisual modules. It implements an interactive amusement park routine featuring touch activation, centrifugal chair expansion, and synchronized lighting. The content illustrates worm gear transmission mechanics alongside physical properties of centrifugal force. It covers touch-activated start-stop control methods alongside multi-module coordinated logic. Furthermore, it examines core design principles uniting mechanical structures, physical phenomena, and responsive user interaction.</p><img loading="lazy" height="1690" width="1690" src="'+o+'" class="common_img" style="width:400px;"><h2 id="_3-47-2-learning-objectives" tabindex="-1">3.47.2 Learning Objectives <a class="header-anchor" href="#_3-47-2-learning-objectives" aria-label="Permalink to &quot;3.47.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand transmission mechanics of worm gear mechanisms, focusing on speed reduction and torque multiplication. Master the physics of centrifugal force, analyzing relationships between rotational velocity and flare angles. Understand operating principles and triggering mechanisms of the touch sensor. Learn daisy-chain wiring methods where multiple modules share an interface port.</p></li><li><p><strong>Skill Objectives</strong>: Assemble the mechanical structure of the spinning swing ride independently, mastering worm gear assembly techniques. Construct basic motor routines to drive smooth ride rotation. Implement a complete interactive sequence comprising touch activation, 5 s rotation, automated stopping, RGB illumination, and dot matrix graphics.</p></li><li><p><strong>Thinking Objectives</strong>: Build transmission system thinking tracing power input, torque multiplication, and motion output, and understand the engineering significance of speed reduction mechanisms. Cultivate observation and analytical skills regarding centrifugal physical phenomena. Strengthen product design thinking centered on tactile touch interactions.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to centrifugal force applications including spinning swing rides, washing machine spin cycles, laboratory centrifuges, and rotating umbrellas. Understand widespread uses of worm gears across elevators, roll-up shutter doors, and industrial speed reducers. Inspire exploration into amusement engineering, physical phenomena, and mechanical power transmission.</p></li></ol><h2 id="_3-47-3-preparation" tabindex="-1">3.47.3 Preparation <a class="header-anchor" href="#_3-47-3-preparation" aria-label="Permalink to &quot;3.47.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>360° block motor</p></li><li><p>RGB light module</p></li><li><p>Dot matrix module</p></li><li><p>Touch sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab graphical programming platform</li></ul><h2 id="_3-47-4-hands-on-project" tabindex="-1">3.47.4 Hands-On Project <a class="header-anchor" href="#_3-47-4-hands-on-project" aria-label="Permalink to &quot;3.47.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Spinning Swing Ride, delivering an interactive attraction featuring touch-to-start activation, centrifugal chair expansion, and timed automatic stopping. The system adopts an architecture combining worm gear speed reduction, centrifugal chair flaring, and touch-activated control. After speed reduction and torque multiplication through a worm gear, the motor smoothly rotates the central column. Under centrifugal force, four hanging swing chairs flare outward automatically. Higher rotational velocities produce wider flare angles, shaping an umbrella-like canopy. Touching the sensor triggers operation, while an RGB red breathing light and an umbrella-themed dot matrix display establish an engaging atmosphere. The ride halts automatically after 5 s, combining physical phenomena with mechanical engineering.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),x(n,{src:"../../_static/shared/pdf/chapter_3/47.pdf"}),e[1]||(e[1]=a('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 360° block motor to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the touch sensor to the dot matrix module using a 4-pin module cable, connect the dot matrix module to the RGB light module using another 4-pin module cable, then connect the combined modules to port <strong>A</strong> of the controller using a third 4-pin module cable.</p></li></ul><img loading="lazy" height="1257" width="2477" src="'+v+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Touch sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+k+'" class="common_img" style="width:800px;"><ul><li>Select <strong>360° Motor</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+P+'" class="common_img" style="width:800px;"><ul><li>Select <strong>Dot matrix module</strong> and <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+q+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+r+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+s+'"></td><td style="text-align:left;">Serve as the main program loop container, continuously executing internal code after power-on initialization.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="85" width="561" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+d+'"></td><td style="text-align:left;">Read the detection status of the touch sensor at the designated port, returning a Boolean value to determine whether human touch is detected.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="145" width="655" src="'+c+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+i+'"></td><td style="text-align:left;">Drive the 360° block motor at a designated port to rotate continuously at a customized speed in the forward or reverse direction.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="91" width="416" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+i+'"></td><td style="text-align:left;">Stop power output to the 360° block motor at the designated port, immediately halting motor rotation.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="64" width="280" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the dot matrix module at the designated port to load and display preset graphic patterns.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="811" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Control the RGB light module at the designated port to activate a breathing color cycle, with customizable transition periods.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="576" src="'+m+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+t+'"></td><td style="text-align:left;">Turn off the RGB light module at the designated port, cutting off light output.</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="513" width="430" src="'+S+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>When the touch sensor is touched, the motor rotates at 100% speed to spin the ride, the RGB light module pulses red with a 1 s breathing cycle, and the dot matrix module displays an open umbrella pattern. Otherwise, rotation stops, the RGB light module turns off, and the dot matrix module switches to an alternative umbrella graphic pattern.</p></li></ul><img loading="lazy" height="542" width="941" src="'+B+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to complete the program transfer and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+u+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1adJTOnyve2MmEehrB9YFSW8echTWwoF2?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-47-5-expansion-and-challenge" tabindex="-1">3.47.5 Expansion and Challenge <a class="header-anchor" href="#_3-47-5-expansion-and-challenge" aria-label="Permalink to &quot;3.47.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Variable-Speed Spinning Swing Ride</strong></p><p>Ramp motor speed gradually from low velocity to 100% upon startup, maintain maximum speed briefly, and decelerate smoothly to a complete stop, shifting RGB colors from blue to green to red to indicate acceleration phases. Practice progressive velocity choreography while understanding soft-start safety engineering in amusement attractions. Extend discussions to smooth acceleration profiles in carousels and observation Ferris wheels.</p><p><strong>Project 2: Musical Spinning Swing Ride</strong></p><p>Program a buzzer to play carnival melodies while rotating, synchronizing musical tempo with RGB light flashes throughout the entire operational cycle. Practice matching musical duration with mechanical runtimes while understanding how background audio enhances immersive visitor experiences. Extend discussions to theme park soundscapes and carousel music box mechanisms.</p><h2 id="_3-47-6-q-a" tabindex="-1">3.47.6 Q&amp;A <a class="header-anchor" href="#_3-47-6-q-a" aria-label="Permalink to &quot;3.47.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why do the swing chairs flare outward when the ride spins, and what physical force causes this expansion?</strong></p><p>Answer: The chairs flare outward due to <strong>centrifugal force</strong>. When an object moves in a circular path, inertia creates a tendency to move outward along a tangential straight line, generating an apparent outward force known as centrifugal force. As the central column spins, each swing chair tends to travel outward in a straight line, but is constrained by its suspending arm and link pin. Consequently, the chair tilts and expands outward as if pulled by an invisible outward tension. Faster rotational speeds generate greater centrifugal force, producing a wider flare angle that lifts the chairs higher into a flatter horizontal plane. When rotation halts, centrifugal force ceases, and gravitational force pulls the chairs vertically downward into rest. Real-world applications of centrifugal force are widespread: washing machines spin rapidly to extract water droplets from clothes, twirling a wet umbrella flings water droplets away from the canopy rim, and passengers experience an outward pull during roller coaster turns. The spinning swing ride in this lesson embodies this foundational physical phenomenon within an interactive mechanical model.</p><p><strong>Question 2: Why does the ride utilize a worm gear mechanism rather than driving the column directly with a motor?</strong></p><p>Answer: A worm gear mechanism delivers two vital engineering benefits: <strong>speed reduction with torque multiplication, and reverse self-locking</strong>. In terms of speed reduction and torque multiplication, standard motors rotate at high velocities but produce limited rotational torque. Driving the heavy swing structure directly would overload the motor, and excessive speeds would compromise operational safety. The worm gear functions as a high-ratio speed reducer where numerous revolutions of the worm screw advance the worm gear by only a fraction of a turn. This reduction lowers output speed while multiplying mechanical torque, enabling a compact motor to spin multiple chairs smoothly. In terms of reverse self-locking, motion transmits solely from the worm screw to the worm gear. External manual forces applied to the chairs cannot backdrive the worm screw, preventing uncontrolled freewheeling or reverse spin when power cuts off. These dual properties make worm gear transmissions essential across elevators, roll-up gates, hoists, and amusement rides that demand high torque alongside reliable fail-safe operation.</p><h2 id="_3-47-7-technical-support-and-product-discussion" tabindex="-1">3.47.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-47-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.47.7 Technical Support and Product Discussion&quot;">​</a></h2><p>Submit questions or share project modifications in the community forum:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+f+'" class="common_img" style="width:800px;"></a>',33))])}const Y=w(z,[["render",T]]);export{K as __pageData,Y as default};
